<!DOCTYPE html>&#10;<html lang="en" class="scroll-smooth">&#10;<head>&#10;    <meta charset="UTF-8">&#10;    <meta name="viewport" content="width=device-width, initial-scale=1.0">&#10;    <title>Create User | Admin Panel</title>&#10;    <script src="https://cdn.tailwindcss.com"></script>&#10;    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">&#10;    <script defer src="https://cdn.jsdelivr.net/npm/alpinejs@3.x.x/dist/cdn.min.js"></script>&#10;    <script>&#10;        tailwind.config = {&#10;            darkMode: &#39;class&#39;,&#10;            theme: {&#10;                extend: {&#10;                    colors: {&#10;                        primary: {&#10;                            50: &#39;#eff6ff&#39;,&#10;                            100: &#39;#dbeafe&#39;,&#10;                            500: &#39;#3b82f6&#39;,&#10;                            600: &#39;#2563eb&#39;,&#10;                            700: &#39;#1d4ed8&#39;,&#10;                        }&#10;                    },&#10;                    animation: {&#10;                        &#39;fade-in&#39;: &#39;fadeIn 0.3s ease-in-out&#39;,&#10;                        &#39;slide-in&#39;: &#39;slideIn 0.3s ease-out&#39;,&#10;                        &#39;bounce-in&#39;: &#39;bounceIn 0.5s ease-out&#39;,&#10;                    },&#10;                    keyframes: {&#10;                        fadeIn: {&#10;                            &#39;0%&#39;: { opacity: &#39;0&#39; },&#10;                            &#39;100%&#39;: { opacity: &#39;1&#39; },&#10;                        },&#10;                        slideIn: {&#10;                            &#39;0%&#39;: { transform: &#39;translateY(-10px)&#39;, opacity: &#39;0&#39; },&#10;                            &#39;100%&#39;: { transform: &#39;translateY(0)&#39;, opacity: &#39;1&#39; },&#10;                        },&#10;                        bounceIn: {&#10;                            &#39;0%&#39;: { transform: &#39;scale(0.9)&#39;, opacity: &#39;0&#39; },&#10;                            &#39;70%&#39;: { transform: &#39;scale(1.05)&#39; },&#10;                            &#39;100%&#39;: { transform: &#39;scale(1)&#39;, opacity: &#39;1&#39; },&#10;                        }&#10;                    }&#10;                }&#10;            }&#10;        }&#10;    </script>&#10;    <style>&#10;        * {&#10;            -webkit-font-smoothing: antialiased;&#10;            -moz-osx-font-smoothing: grayscale;&#10;        }&#10;        &#10;        .card-hover {&#10;            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);&#10;        }&#10;        &#10;        .card-hover:hover {&#10;            transform: translateY(-2px);&#10;            box-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.15);&#10;        }&#10;        &#10;        .scrollbar-thin::-webkit-scrollbar {&#10;            width: 6px;&#10;            height: 6px;&#10;        }&#10;        &#10;        .scrollbar-thin::-webkit-scrollbar-track {&#10;            background: #f1f5f9;&#10;        }&#10;        &#10;        .scrollbar-thin::-webkit-scrollbar-thumb {&#10;            background: #cbd5e1;&#10;            border-radius: 10px;&#10;        }&#10;    </style>&#10;</head>&#10;<body class="bg-gray-50 dark:bg-gray-900 font-sans">&#10;    <div x-data="{ sidebarOpen: false }" class="flex min-h-screen">&#10;        &#10;        @include(&#39;layouts.sidebar-admin&#39;)&#10;&#10;        <!-- Mobile Menu Button -->&#10;        <div class="lg:hidden fixed top-4 left-4 z-50">&#10;            <button @click="sidebarOpen = !sidebarOpen" &#10;                    class="p-2 rounded-lg bg-white dark:bg-gray-800 shadow-lg text-gray-600 dark:text-gray-300">&#10;                <i class="fas fa-bars text-xl"></i>&#10;            </button>&#10;        </div>&#10;&#10;        <!-- Main Content -->&#10;        <div class="flex-1 flex flex-col overflow-hidden">&#10;            <!-- Header -->&#10;            <header class="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 shadow-sm">&#10;                <div class="px-6 py-4">&#10;                    <div class="flex items-center justify-between">&#10;                        <div class="flex items-center pl-12 lg:pl-0">&#10;                            <div>&#10;                                <h1 class="text-2xl font-bold text-gray-900 dark:text-white flex items-center">&#10;                                    <i class="fas fa-user-plus mr-3 text-violet-500"></i>&#10;                                    Create New User&#10;                                    <span class="ml-3 text-xs bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300 font-bold px-3 py-1 rounded-full">&#10;                                        Add admin, manager or user&#10;                                    </span>&#10;                                </h1>&#10;                                <p class="text-sm text-gray-600 dark:text-gray-300 mt-1 flex items-center">&#10;                                    <i class="fas fa-user-cog text-xs mr-2"></i>&#10;                                    Complete the form below to create a new account&#10;                                </p>&#10;                            </div>&#10;                        </div>&#10;                        &#10;                        <div class="flex items-center space-x-4">&#10;                            <!-- Dark Mode Toggle -->&#10;                            <button onclick="toggleDarkMode()"&#10;                                class="p-2.5 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-xl transition-colors">&#10;                                <i class="fas fa-moon text-lg dark:hidden"></i>&#10;                                <i class="fas fa-sun text-lg hidden dark:inline"></i>&#10;                            </button>&#10;                            &#10;                            <a href="{{ route(&#39;users.index&#39;) }}" class="bg-gray-500 hover:bg-gray-600 text-white font-semibold py-3 px-5 rounded-xl shadow-md hover:shadow-lg transition-all duration-200 flex items-center gap-3">&#10;                                <i class="fas fa-arrow-left"></i>&#10;                                Back to Users&#10;                            </a>&#10;                        </div>&#10;                    </div>&#10;                </div>&#10;            </header>&#10;&#10;            <!-- Main Content Area -->&#10;            <main class="flex-1 overflow-y-auto scrollbar-thin p-6 bg-gradient-to-b from-gray-50 to-white dark:from-gray-900 dark:to-gray-800">&#10;                <div class="max-w-2xl mx-auto">&#10;                    &#10;                    <!-- Form Card -->&#10;                    <div class="bg-white dark:bg-gray-800 rounded-2xl shadow-xl border border-gray-100 dark:border-gray-700 overflow-hidden card-hover">&#10;                        &#10;                        <!-- Card Header -->&#10;                        <div class="px-8 py-6 border-b border-gray-200 dark:border-gray-700 bg-gradient-to-r from-gray-50 to-white dark:from-gray-800 dark:to-gray-700">&#10;                            <div class="flex items-center justify-between">&#10;                                <div>&#10;                                    <h3 class="text-xl font-bold text-gray-900 dark:text-white">New User Details</h3>&#10;                                    <p class="text-sm text-gray-600 dark:text-gray-300 mt-1">Fill in all required fields</p>&#10;                                </div>&#10;                            </div>&#10;                        </div>&#10;&#10;                        <!-- Form -->&#10;                        <form action="{{ route(&#39;users.store&#39;) }}" method="POST" class="p-8 space-y-6">&#10;                            @csrf&#10;&#10;                            <div>&#10;                                <label class="block text-gray-700 dark:text-gray-200 font-semibold text-sm mb-3">&#10;                                    Full Name <span class="text-red-500">*</span>&#10;                                </label>&#10;                                <div class="relative">&#10;                                    <div class="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">&#10;                                        <i class="fas fa-user text-gray-400"></i>&#10;                                    </div>&#10;                                    <input type="text" name="name" required autofocus&#10;                                           class="w-full pl-12 pr-4 py-4 border border-gray-200 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-xl focus:ring-2 focus:ring-violet-500 focus:border-transparent transition-all"&#10;                                           placeholder="Enter full name">&#10;                                </div>&#10;                                @error(&#39;name&#39;)&#10;                                    <p class="mt-2 text-sm text-red-600 dark:text-red-400">{{ $message }}</p>&#10;                                @enderror&#10;                            </div>&#10;&#10;                            <div>&#10;                                <label class="block text-gray-700 dark:text-gray-200 font-semibold text-sm mb-3">&#10;                                    Email Address <span class="text-red-500">*</span>&#10;                                </label>&#10;                                <div class="relative">&#10;                                    <div class="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">&#10;                                        <i class="fas fa-envelope text-gray-400"></i>&#10;                                    </div>&#10;                                    <input type="email" name="email" required&#10;                                           class="w-full pl-12 pr-4 py-4 border border-gray-200 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-xl focus:ring-2 focus:ring-violet-500 focus:border-transparent transition-all"&#10;                                           placeholder="user@example.com">&#10;                                </div>&#10;                                @error(&#39;email&#39;)&#10;                                    <p class="mt-2 text-sm text-red-600 dark:text-red-400">{{ $message }}</p>&#10;                                @enderror&#10;                            </div>&#10;&#10;                            <div>&#10;                                <label class="block text-gray-700 dark:text-gray-200 font-semibold text-sm mb-3">&#10;                                    Role <span class="text-red-500">*</span>&#10;                                </label>&#10;                                <div class="relative">&#10;                                    <div class="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">&#10;                                        <i class="fas fa-user-tag text-gray-400"></i>&#10;                                    </div>&#10;                                    <select name="role" required&#10;                                            class="w-full pl-12 pr-10 py-4 border border-gray-200 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-xl focus:ring-2 focus:ring-violet-500 focus:border-transparent appearance-none">&#10;                                        <option value="">Select a role</option>&#10;                                        <option value="user">User - View only access</option>&#10;                                        <option value="manager">Manager - Content management</option>&#10;                                        <option value="admin">Admin - Full system access</option>&#10;                                    </select>&#10;                                    <div class="absolute inset-y-0 right-0 pr-4 flex items-center pointer-events-none">&#10;                                        <i class="fas fa-chevron-down text-gray-400"></i>&#10;                                    </div>&#10;                                </div>&#10;                                @error(&#39;role&#39;)&#10;                                    <p class="mt-2 text-sm text-red-600 dark:text-red-400">{{ $message }}</p>&#10;                                @enderror&#10;                            </div>&#10;&#10;                            <div>&#10;                                <label class="block text-gray-700 dark:text-gray-200 font-semibold text-sm mb-3">&#10;                                    Password <span class="text-red-500">*</span>&#10;                                </label>&#10;                                <div class="relative">&#10;                                    <div class="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">&#10;                                        <i class="fas fa-lock text-gray-400"></i>&#10;                                    </div>&#10;                                    <input type="password" name="password" required&#10;                                           class="w-full pl-12 pr-4 py-4 border border-gray-200 dark:border-gray-600 dark:bg-gray-700 dark:text-white rounded-xl focus:ring-2 focus:ring-violet-500 focus:border-transparent transition-all"&#10;                                           placeholder="Minimum 8 characters">&#10;                                </div>&#10;                                @error(&#39;password&#39;)&#10;                                    <p class="mt-2 text-sm text-red-600 dark:text-red-400">{{ $message }}</p>&#10;                                @enderror&#10;                                <p class="text-xs text-gray-500 dark:text-gray-400 mt-2">Minimum 8 characters required</p>&#10;                            </div>&#10;&#10;                            <div class="flex flex-col sm:flex-row gap-4 pt-2">&#10;                                <a href="{{ route(&#39;users.index&#39;) }}"&#10;                                   class="order-2 sm:order-1 flex-1 bg-gray-500 hover:bg-gray-600 text-white font-semibold py-4 px-6 rounded-xl shadow-md hover:shadow-lg transition-all duration-200 text-center">&#10;                                    <i class="fas fa-arrow-left mr-2"></i>Cancel&#10;                                </a>&#10;                                <button type="submit"&#10;                                        class="order-1 sm:order-2 flex-1 bg-gradient-to-r from-violet-600 to-purple-500 hover:from-violet-700 hover:to-purple-600 text-white font-semibold py-4 px-6 rounded-xl shadow-md hover:shadow-lg transition-all duration-200 flex items-center justify-center gap-2">&#10;                                    <i class="fas fa-user-plus"></i>&#10;                                    Create User&#10;                                </button>&#10;                            </div>&#10;                        </form>&#10;                    </div>&#10;                </div>&#10;            </main>&#10;        </div>&#10;    </div>&#10;&#10;    <script>&#10;        // Dark mode toggle&#10;        function toggleDarkMode() {&#10;            document.documentElement.classList.toggle(&#39;dark&#39;);&#10;            localStorage.setItem(&#39;darkMode&#39;, document.documentElement.classList.contains(&#39;dark&#39;));&#10;        }&#10;&#10;        // Initialize dark mode&#10;        if (localStorage.getItem(&#39;darkMode&#39;) === &#39;true&#39;) {&#10;            document.documentElement.classList.add(&#39;dark&#39;);&#10;        }&#10;    </script>&#10;</body>&#10;</html>
